  'ಶನಿ': {
    'ರವಿ':
        'शनि-सूर्य की अवधि में अधिकारी वर्ग से मतभेद तथा पद हानि की आशंका रहती है। आर्थिक संकट, व्यय वृद्धि तथा सरकारी कार्यों में बाधा उत्पन्न होती है। हड्डी संबंधी रोग, नेत्र विकार, हृदय रोग तथा शारीरिक दुर्बलता बढ़ती है। पिता से तनाव, पारिवारिक कलह तथा सामाजिक प्रतिष्ठा में गिरावट हो सकती है।',
    'ಚಂದ್ರ':
        'शनि-चंद्र की अवधि में मानसिक कष्ट, निराशा एवं उदासीनता बढ़ती है। आर्थिक हानि, कार्य में विलंब तथा जीवन में निरंतर कठिनाइयाँ आती हैं। वात-कफ विकार, जल जनित रोग, अनिद्रा तथा मानसिक अवसाद की संभावना रहती है। माता को कष्ट, गृह सुख में कमी तथा पारिवारिक संबंधों में शीतलता आ सकती है।',
    'ಕುಜ':
        'शनि-मंगल की अवधि अत्यंत कठिन होती है, दुर्घटना एवं विवाद की प्रबल संभावना रहती है। आर्थिक हानि, शत्रुओं से भय, न्यायालयीन विवाद तथा कार्यक्षेत्र में गंभीर बाधाएँ आती हैं। हड्डी टूटना, शल्य क्रिया, रक्त विकार तथा वात-पित्त का प्रकोप होता है। भाइयों से शत्रुता, क्रोध, हिंसा तथा पारिवारिक विघटन की स्थिति बन सकती है।',
    'ರಾಹು':
        'शनि-राहु की अवधि जीवन की सबसे कठिन अवधियों में से एक मानी जाती है। आर्थिक संकट, बेरोजगारी, ऋण, चोरी तथा सर्वत्र पराजय की स्थिति बनती है। दीर्घकालिक रोग, विषाक्तता, मानसिक विकार तथा अज्ञात रोगों की प्रबल संभावना रहती है। पारिवारिक विघटन, सामाजिक अपमान, एकाकीपन तथा अवसाद की स्थिति बनती है।',
    'ಗುರು':
        'शनि-बृहस्पति की अवधि में गुरु की कृपा से कठिनाइयों में कमी आती है। धीमी गति से किंतु स्थिर उन्नति होती है, धार्मिक कार्यों तथा सेवा से धन लाभ संभव है। स्वास्थ्य में सुधार होता है, किंतु वात रोग एवं यकृत संबंधी समस्या बनी रह सकती है। गुरुजनों का मार्गदर्शन मिलता है, संतान सुख तथा पारिवारिक स्थिरता में वृद्धि होती है।',
    'ಶನಿ':
        'शनि-शनि की अवधि में कठिन परिश्रम, विलंब तथा धैर्य की परीक्षा होती है। आर्थिक तंगी, कार्य में रुकावट तथा अत्यंत धीमी प्रगति होती है। वात रोग, जोड़ों का दर्द, हड्डियों की कमजोरी तथा दीर्घकालिक रोगों की संभावना रहती है। परिवार में शीतलता, एकाकीपन, वृद्धजनों की सेवा तथा कर्तव्यों का बोझ बढ़ता है।',
    'ಬುಧ':
        'शनि-बुध की अवधि में बौद्धिक कार्यों में धीमी किंतु स्थिर प्रगति होती है। व्यापार, लेखा, गणना तथा प्रशासनिक कार्यों में सफलता मिलती है। तंत्रिका दुर्बलता, वात विकार, त्वचा रोग तथा श्वसन संबंधी समस्या हो सकती है। मित्रों से सीमित सहयोग मिलता है, सामाजिक जीवन में सतर्कता आवश्यक है।',
    'ಕೇತು':
        'शनि-केतु की अवधि में आध्यात्मिक प्रवृत्ति बढ़ती है किंतु भौतिक जीवन कष्टमय रहता है। कार्यक्षेत्र में अचानक हानि, बेरोजगारी तथा अनिश्चितता की स्थिति बनती है। पेट संबंधी रोग, जोड़ों का दर्द, अज्ञात रोग तथा मानसिक अशांति होती है। परिवार में अलगाव, सामाजिक एकांत तथा निराशा की भावना बढ़ सकती है।',
    'ಶುಕ್ರ':
        'शनि-शुक्र की अवधि में भौतिक सुखों की प्राप्ति होती है किंतु विलंब से। वाहन, भवन, आभूषण तथा विलासिता की वस्तुओं की प्राप्ति धीमी गति से होती है। मधुमेह, प्रजनन तंत्र, मूत्र रोग तथा वात विकार की संभावना रहती है। वैवाहिक जीवन में तनाव, प्रेम संबंधों में शीतलता तथा विलंबित सुख की प्राप्ति होती है।',
  },

  // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  // बुध महादशा (Mercury Mahadasha)
  // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  'ಬುಧ': {
    'ರವಿ':
        'बुध-सूर्य की अवधि में बौद्धिक कार्यों में राजकीय सहयोग एवं मान्यता मिलती है। शिक्षा, प्रशासन, लेखन तथा सरकारी क्षेत्र में विशेष उन्नति होती है। तंत्रिका तंत्र, त्वचा रोग तथा नेत्र संबंधी समस्या हो सकती है। पिता से सहयोग, मित्रों से लाभ तथा सामाजिक प्रतिष्ठा में वृद्धि होती है।',
    'ಚಂದ್ರ':
        'बुध-चंद्र की अवधि में कल्पनाशक्ति, सृजनात्मकता एवं भावनात्मक बुद्धि बढ़ती है। व्यापार, शिक्षा, कला तथा संचार के क्षेत्र में अच्छा लाभ होता है। कफ प्रधान रोग, मानसिक चंचलता तथा तंत्रिका संबंधी दुर्बलता हो सकती है। माता से सुख, गृह सुख तथा पारिवारिक संबंधों में मधुरता बनी रहती है।',
    'ಕುಜ':
        'बुध-मंगल की अवधि में तीव्र बुद्धि, तर्कशक्ति एवं निर्णय क्षमता बढ़ती है। तकनीकी, इंजीनियरिंग, गणित तथा व्यापार में लाभ होता है, किंतु विवादों से सावधान रहना चाहिए। तंत्रिका तंत्र, रक्त विकार, त्वचा रोग तथा दुर्घटना की संभावना रहती है। मित्रों से मतभेद, वाक्‌युद्ध तथा भाइयों से तनाव हो सकता है।',
    'ರಾಹು':
